191: function inputVector() {
192:   let ix = 0, iy = 0, mag = 1;
193:   if (keys.has('KeyA') || keys.has('ArrowLeft')) ix -= 1;
194:   if (keys.has('KeyD') || keys.has('ArrowRight')) ix += 1;
195:   if (keys.has('KeyW') || keys.has('ArrowUp')) iy -= 1;
196:   if (keys.has('KeyS') || keys.has('ArrowDown')) iy += 1;
197:   if (ix || iy) {
198:     const l = Math.hypot(ix, iy);
199:     return { x: ix / l, y: iy / l, mag: 1 };
200:   }
201:   if (stick.active && (stick.x || stick.y)) {
202:     const l = Math.hypot(stick.x, stick.y);
203:     if (l > 0.08) return { x: stick.x / Math.max(1, l), y: stick.y / Math.max(1, l), mag: Math.min(1, l) };
204:   }
205:   if (pointer.active && !isTouch) {
206:     const wx = game.cam.x + (pointer.x - view.w / 2) / game.cam.zoom;
207:     const wy = game.cam.y + (pointer.y - view.h / 2) / game.cam.zoom;
208:     const dx = wx - game.player.x, dy = wy - game.player.y;
209:     const d = Math.hypot(dx, dy);
210:     if (d > 14) return { x: dx / d, y: dy / d, mag: clamp(d / 150, 0.25, 1) };
211:   }
212:   return { x: 0, y: 0, mag: 0 };
213: }
