240: function randomZonePoint(zone, nearPath = true) {
241:   const spread = nearPath ? 520 : 700;
242:   let x = between(Math.random, zone.x0 + 120, zone.x1 - 120);
243:   let y = clamp(pathY(x) + between(Math.random, -spread, spread), 80, WORLD_H - 80);
244:   // keep plants and bugs out of the water
245:   for (let tries = 0; tries < 14; tries++) {
246:     let wet = false;
247:     for (const pd of game.puddles) {
248:       const ex = (x - pd.x) / (pd.rx * 1.18);
249:       const ey = (y - pd.y) / (pd.ry * 1.35);
250:       if (ex * ex + ey * ey < 1) { wet = true; break; }
251:     }
252:     if (!wet) break;
253:     x = between(Math.random, zone.x0 + 120, zone.x1 - 120);
254:     y = clamp(pathY(x) + between(Math.random, -spread, spread), 80, WORLD_H - 80);
255:   }
256:   return { x, y };
257: }
