264:     const x = zone.x0 + 140 + ((i + 0.5) / zone.puddles) * (zone.x1 - zone.x0 - 280) + between(rnd, -70, 70);
265:     // leave the sleeping queen's clearing dry
266:     if (zi === 3 && Math.abs(x - 6780) < 220) continue;
267:     const y = pathY(x) + between(rnd, -95, 95);
268:     const rx = between(rnd, 46, 80);
269:     const ry = between(rnd, 26, 41);
270:     game.puddles.push({
271:       x, y, rx, ry, rot: between(rnd, -0.25, 0.25), seed: rnd() * 9,
272:       palette: P, drinking: false, ripples: rnd() * 4,
273:     });
274:   }
275: }
